const DUMMY_EVENTS = [
  {
    id: 'e1',
    title: 'Some Event',
  },
  {
    id: 'e2',
    title: 'Another Event',
  }
];


function EventsPage() {
  return (
    <div>
      <h1>Events Page</h1>
      <ul>
        {DUMMY_EVENTS.map((event) => (
          <li key={event.id}>
            <h2>{event.title}</h2>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default EventsPage;
